components.css:
.pmd{display:grid;grid-template-columns:260px 1fr;gap:14px;font-size:13px;color:var(--text);min-height:360px}
.pmd-side{background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:10px;overflow:auto}
.pmd-search{display:flex;align-items:center;gap:6px;background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:7px 10px;margin-bottom:10px;color:var(--text3)}
.pmd-search input{border:0;background:transparent;color:var(--text);outline:none;width:100%}
.pmd-group{font-size:11px;color:var(--text3);font-weight:700;text-transform:uppercase;letter-spacing:.04em;margin:10px 4px 4px}
.pmd-dev{display:flex;align-items:center;gap:8px;width:100%;text-align:left;background:transparent;border:1px solid transparent;border-radius:8px;padding:8px 10px;color:var(--text);cursor:pointer}
.pmd-dev small{color:var(--text3);font-weight:400}
.pmd-dev:hover{background:var(--bg3)}
.pmd-dev.active{background:var(--accent-soft,rgba(59,130,246,.12));border-color:var(--accent)}
.pmd-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.pmd-dot.ok{background:var(--success,#3fb950)} .pmd-dot.warn{background:var(--warning,#e6a23c)}
.pmd-tag{margin-left:auto;font-size:10px;background:rgba(230,162,60,.15);color:var(--warning,#e6a23c);border-radius:99px;padding:1px 7px;font-weight:700}
.pmd-main{background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:18px 20px;overflow:auto}
.pmd-h{display:flex;align-items:center;gap:10px;margin-bottom:4px}
.pmd-h b{font-size:16px}
.pmd-sub{color:var(--text3);font-size:12px;margin-bottom:16px}
.pmd-tbl{width:100%;border-collapse:collapse}
.pmd-tbl th{text-align:left;font-size:11px;color:var(--text3);text-transform:uppercase;padding:8px 6px;border-bottom:1px solid var(--border)}
.pmd-tbl td{padding:9px 6px;border-bottom:1px solid var(--border)}
.pmd-metric{font-weight:600}
.pmd-val{font-family:var(--font-mono,monospace);font-weight:700}
.pmd-oid{font-family:var(--font-mono,monospace);font-size:11px;color:var(--text3)}
.pmd-miss{color:var(--warning,#e6a23c);font-weight:600}
.pmd-fix{background:var(--accent);color:#fff;border:0;border-radius:7px;padding:5px 12px;font-size:12px;font-weight:600;cursor:pointer}
.pmd-ok{background:var(--bg3);border:1px solid var(--border);border-radius:7px;padding:5px 10px;font-size:12px;color:var(--success,#3fb950);font-weight:600}

